'use strict';
const {test}=require('node:test'); const assert=require('node:assert/strict');
const G=require('./garage'); const {makeMemoryGarageAdapter,synchronizeGarage}=require('./garage-sync');
const vehicle={id:'car1',name:'Voiture',fuel:'Gazole',consumption:6,tankCapacity:50,illustration:'suv',fillPercent:80};
const first=()=>G.addVehicle(G.emptyGarage(),vehicle);
test('V72 first device saves garage with CAS',async()=>{const a=makeMemoryGarageAdapter();const x=await synchronizeGarage({local:first(),baseRevision:0,adapter:a});assert.equal(x.status,'saved');assert.equal(x.server.revision,1);assert.equal((await a.read()).vehicles.length,1)});
test('V72 second device cannot overwrite changed server',async()=>{const a=makeMemoryGarageAdapter();await synchronizeGarage({local:first(),baseRevision:0,adapter:a});const x=await synchronizeGarage({local:first(),baseRevision:0,adapter:a});assert.equal(x.status,'conflict');assert.equal(x.server.vehicles[0].id,'car1')});
test('V72 unchanged garage does not write',async()=>{let writes=0;const a=makeMemoryGarageAdapter();const x=await synchronizeGarage({local:G.emptyGarage(),baseRevision:0,adapter:{read:()=>a.read(),compareAndSwap:()=>{writes++;throw Error('unexpected')}}});assert.equal(x.status,'unchanged');assert.equal(writes,0)});
test('V72 multiple offline edits are one atomic write',async()=>{const a=makeMemoryGarageAdapter();const local=G.editVehicle(first(),'car1',{fillPercent:45});const x=await synchronizeGarage({local,baseRevision:0,adapter:a});assert.equal(x.status,'saved');assert.equal(x.server.revision,1);assert.equal(x.server.vehicles[0].fillPercent,45)});
test('V72 concurrent writes: exactly one wins',async()=>{const a=makeMemoryGarageAdapter();const [x,y]=await Promise.all([synchronizeGarage({local:first(),baseRevision:0,adapter:a}),synchronizeGarage({local:G.addVehicle(G.emptyGarage(),{...vehicle,id:'car2'}),baseRevision:0,adapter:a})]);assert.deepEqual([x.status,y.status].sort(),['conflict','saved']);assert.equal((await a.read()).revision,1)});
test('V72 abort before read does not touch adapter',async()=>{const ac=new AbortController();ac.abort();const x=await synchronizeGarage({local:first(),baseRevision:0,signal:ac.signal,adapter:{read:()=>{throw Error('read called')},compareAndSwap:()=>{throw Error('write called')}}});assert.equal(x.status,'cancelled')});
test('V72 invalid adapter cannot silently claim save',async()=>{await assert.rejects(synchronizeGarage({local:first(),baseRevision:0,adapter:{read:async()=>G.emptyGarage(),compareAndSwap:async()=>({status:'saved',server:G.emptyGarage()})}}),/inconsistent/)});
test('V72 invalid server garage is rejected',async()=>{await assert.rejects(synchronizeGarage({local:first(),baseRevision:0,adapter:{read:async()=>({revision:0,vehicles:[vehicle],defaultVehicleId:'missing'}),compareAndSwap:async()=>null}}),/default/)});
